sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader backdrop;
uniform float strength;
uniform float invert;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return half4(0.0);
    float lum = dot(float3(src.rgb) / float(src.a), float3(0.2126, 0.7152, 0.0722));
    if (invert > 0.5) lum = 1.0 - lum;
    float r = max(strength, 0.0) * clamp(lum, 0.0, 1.0);
    if (r < 0.5) return backdrop.eval(coord) * src.a;
    float spin = fract(sin(dot(floor(coord), float2(12.9898, 78.233))) * 43758.5453) * 6.2831853;
    half4 sum = half4(0.0);
    for (int i = 0; i < 64; i++) {
        float k = (float(i) + 0.5) / 64.0;
        float a = float(i) * 2.3999632 + spin;
        sum += backdrop.eval(coord + sqrt(k) * r * float2(cos(a), sin(a)));
    }
    return sum * (src.a / 64.0);
}
